func TestFileIsAgreesWithTheSharedVerdict(t *testing.T) {
	for _, v := range sharedFileVectors {
		if got := FileIs(v.data, v.mediaType); got != v.want {
			t.Errorf("%s: FileIs = %v, the shared rule says %v", v.name, got, v.want)
		}
	}
}
